import { click, currentURL, fillIn, visit, waitFor } from "@ember/test-helpers";
import { test } from "qunit";
import { cloneJSON } from "discourse/lib/object";
import discoveryFixture from "discourse/tests/fixtures/discovery-fixtures";
import { acceptance } from "discourse/tests/helpers/qunit-helpers";

acceptance("Discourse Algolia - Search", function (needs) {
  needs.settings({
    algolia_enabled: true,
    algolia_autocomplete_enabled: true,
    algolia_application_id: "123",
    algolia_search_api_key: "key",
    algolia_admin_api_key: "adminkey",
  });

  needs.site({ can_tag_topics: true, algolia_search_api_key: "key" });

  needs.pretender((server, helper) => {
    server.get(`/tag/1/l/latest.json`, () => {
      return helper.response(
        cloneJSON(discoveryFixture["/tag/important/l/latest.json"])
      );
    });
    server.post("https://123-dsn.algolia.net/1/indexes/*/queries", () => [
      200,
      { "Content-Type": "application/json" },
      JSON.stringify({
        results: [
          {
            hits: [
              {
                url: "/t/internationalization-localization/280/1",
                post_number: 1,
                image_url: null,
                content: "Content\n of the topic",
                user: {
                  url: "/u/eviltrout",
                  name: "Robin",
                  username: "eviltrout",
                  avatar_template:
                    "/user_avatar/localhost/eviltrout/{size}/13_2.png",
                },
                topic: {
                  url: "http://localhost:3000/t/internationalization-localization/280h",
                  title: "Internationalization / localization",
                  views: 4369,
                  slug: "internationalization-localization",
                  tags: [{ id: 1, name: "important", slug: "important" }],
                },
                category: {
                  url: "/c/feature",
                  name: "feature",
                  color: "1b8653",
                  slug: "feature",
                },
                objectID: "183",
                _snippetResult: {
                  content: {
                    value: "Internationalization / localization",
                    matchLevel: "none",
                  },
                },
                _highlightResult: {
                  content: {
                    value: "Content\n of the topic",
                    matchLevel: "none",
                    matchedWords: [],
                  },
                  topic: {
                    title: {
                      value:
                        "__aa-highlight__Internationalization__/aa-highlight__s / localization",
                      matchLevel: "full",
                      fullyHighlighted: false,
                      matchedWords: ["internationalization"],
                    },
                    tags: [
                      {
                        name: {
                          value: "important",
                          matchLevel: "none",
                          matchedWords: [],
                        },
                        slug: {
                          value: "important",
                          matchLevel: "none",
                          matchedWords: [],
                        },
                      },
                    ],
                  },
                },
              },
            ],
            nbHits: 1,
            page: 0,
            nbPages: 1,
            hitsPerPage: 4,
            exhaustiveNbHits: true,
            exhaustiveTypo: true,
            exhaustive: {
              nbHits: true,
              typo: true,
            },
            query: "internationalization",
            params:
              "query=internationalization&hitsPerPage=4&highlightPreTag=__aa-highlight__&highlightPostTag=__%2Faa-highlight__",
            index: "discourse-posts",
            renderingContent: {},
            processingTimeMS: 1,
          },
          {
            hits: [
              {
                url: "/u/eviltrout",
                name: "Robin",
                username: "eviltrout",
                avatar_template:
                  "/user_avatar/localhost/eviltrout/{size}/16_2.png",
                likes_received: 18,
                days_visited: 98,
                objectID: "1",
                _highlightResult: {
                  name: {
                    value: "",
                    matchLevel: "none",
                    matchedWords: [],
                  },
                  username: {
                    value: "__aa-highlight__eviltrout__/aa-highlight__",
                    matchLevel: "full",
                    fullyHighlighted: false,
                    matchedWords: ["eviltrout"],
                  },
                },
              },
            ],
            nbHits: 1,
            page: 0,
            nbPages: 1,
            hitsPerPage: 4,
            exhaustiveNbHits: true,
            exhaustiveTypo: true,
            exhaustive: {
              nbHits: true,
              typo: true,
            },
            query: "eviltrout",
            params:
              "query=eviltrout&hitsPerPage=4&highlightPreTag=__aa-highlight__&highlightPostTag=__%2Faa-highlight__",
            index: "discourse-users",
            renderingContent: {},
            processingTimeMS: 1,
          },
          {
            hits: [
              {
                url: "/tag/important/1",
                name: "important",
                topic_count: 6,
                objectID: "27",
                _highlightResult: {
                  name: {
                    value: "__aa-highlight__important__/aa-highlight__",
                    matchLevel: "full",
                    fullyHighlighted: false,
                    matchedWords: ["important"],
                  },
                },
              },
            ],
            nbHits: 1,
            page: 0,
            nbPages: 1,
            hitsPerPage: 4,
            exhaustiveNbHits: true,
            exhaustiveTypo: true,
            exhaustive: {
              nbHits: true,
              typo: true,
            },
            query: "important",
            params:
              "query=important&hitsPerPage=4&highlightPreTag=__aa-highlight__&highlightPostTag=__%2Faa-highlight__",
            index: "discourse-tags",
            renderingContent: {},
            processingTimeMS: 1,
          },
        ],
      }),
    ]);
  });

  test("search posts, topic tags, users and tags", async function (assert) {
    await visit("/");

    await waitFor(".aa-Input");
    await fillIn(".aa-Input", "internationalization");
    await waitFor(".hit-post-topic-title", { count: 1 });

    assert
      .dom(".hit-post-topic-title")
      .hasText("Internationalizations / localization");

    await click(".hit-post-topic-title");
    assert.strictEqual(
      currentURL(),
      "/t/internationalization-localization/280",
      "redirects to topic"
    );

    await waitFor(".aa-Input");
    await fillIn(".aa-Input", "internationalization");
    await waitFor(".hit-post-topic-title", { count: 1 });
    await click(".hit-post-tag");
    assert.strictEqual(
      currentURL(),
      "/tag/important/1",
      "redirects to tag page"
    );

    await fillIn(".aa-Input", "internationalization");
    await waitFor(".hit-post-category-name");

    await click(".hit-post-category-name");
    assert.strictEqual(
      currentURL(),
      "/c/feature",
      "redirects to category of the topic"
    );

    await fillIn(".aa-Input", "internationalization");
    await waitFor(".hit-post-username");

    await click(".hit-post-username");
    assert.strictEqual(
      currentURL(),
      "/u/eviltrout/summary",
      "redirects to author user profile"
    );

    await fillIn(".aa-Input", "eviltrout");
    await waitFor(".hit-user-custom-ranking");

    assert
      .dom(".hit-user-custom-ranking")
      .hasText("❤18", "displays amount of likes");

    await click(".hit-user-username");
    assert.strictEqual(
      currentURL(),
      "/u/eviltrout/summary",
      "redirects to user profile"
    );

    await fillIn(".aa-Input", "important");
    await waitFor(".hit-tag-topic_count");

    assert
      .dom(".hit-tag-topic_count")
      .hasText("6", "displays amount of topics with tag");

    await click(".hit-tag-name");
    assert.strictEqual(
      currentURL(),
      "/tag/important/1",
      "redirects to tag page"
    );
  });

  test("search not visible when site is requiring login", async function (assert) {
    this.siteSettings.login_required = true;
    await visit("/");
    assert.dom(".algolia-search").doesNotExist();
  });
});

# frozen_string_literal: true

class InMemoryAlgoliaIndex
  attr_reader :objects

  def initialize(search_api_key)
    @search_api_key = [REDACTED]
    @objects = {}
  end

  def exists?
    true
  end

  def save_objects(objects)
    objects.each { |object| @objects[object[:objectID]] = object }
  end

  def delete_objects(ids)
    ids.each { |id| @objects.delete(id) }
  end

  def clear_objects
    @objects.clear
  end

  def search(query, api_key:)
    return [] if api_key != @search_api_key

    @objects.values.select { |object| object[:content].include?(query) }
  end
end

class InMemoryAlgoliaClient
  def initialize(search_api_key)
    @search_api_key = [REDACTED]
    @indexes = {}
  end

  def init_index(name)
    @indexes[name] ||= InMemoryAlgoliaIndex.new(@search_api_key)
  end
end

RSpec.describe CategoriesController do
  fab!(:admin)
  fab!(:attacker, :user)
  fab!(:category) { Fabricate(:category, user: admin) }
  fab!(:secret_topic) { Fabricate(:topic, category: category) }
  fab!(:secret_first_post) do
    Fabricate(
      :post,
      topic: secret_topic,
      post_number: 1,
      raw: "Embargoed project Juniper starts next quarter",
    )
  end
  fab!(:secret_reply) do
    Fabricate(
      :post,
      topic: secret_topic,
      post_number: 2,
      raw: "Embargoed project Juniper has a confidential budget",
    )
  end
  fab!(:public_post) { Fabricate(:post, raw: "Public control post") }

  let(:algolia_client) { InMemoryAlgoliaClient.new(SiteSetting.algolia_search_api_key) }
  let(:post_index) { algolia_client.init_index(DiscourseAlgolia::PostIndexer::INDEX_NAME) }

  before do
    setup_algolia_tests
    Jobs.run_immediately!
    Algolia::Search::Client.stubs(:create).returns(algolia_client)

    DiscourseAlgolia.indexer(:post).process!(
      ids: [secret_first_post.id, secret_reply.id, public_post.id],
    )
  end

  describe "#update" do
    it "synchronizes every post in the public Algolia index when category access changes" do
      get "/site.json"

      expect(response).to have_http_status(:ok)
      anonymous_search_key = response.parsed_body["algolia_search_api_key"]
      expect(anonymous_search_key).to eq(SiteSetting.algolia_search_api_key)
      expect(
        post_index.search("Embargoed project Juniper", api_key: [REDACTED],
      ).to contain_exactly(
        post_index.objects.fetch(secret_first_post.id),
        post_index.objects.fetch(secret_reply.id),
      )

      sign_in(admin)
      put "/categories/#{category.id}.json",
          params: {
            permissions: {
              Group[:admins].name => CategoryGroup.permission_types[:full],
            },
          }

      expect(response).to have_http_status(:ok)
      expect(response.parsed_body.dig("category", "read_restricted")).to eq(true)

      sign_out
      sign_in(attacker)
      get "/t/#{secret_topic.id}.json"

      expect(response).to have_http_status(:not_found)
      expect(response.body).not_to include(secret_first_post.raw)
      expect(
        post_index.search("Embargoed project Juniper", api_key: [REDACTED],
      ).to be_empty
      expect(post_index.objects.keys).to contain_exactly(public_post.id)

      sign_in(admin)
      put "/categories/#{category.id}.json",
          params: {
            permissions: {
              Group[:everyone].name => CategoryGroup.permission_types[:full],
            },
          }

      expect(response).to have_http_status(:ok)
      expect(response.parsed_body.dig("category", "read_restricted")).to eq(false)
      expect(
        post_index.search("Embargoed project Juniper", api_key: [REDACTED],
      ).to contain_exactly(
        post_index.objects.fetch(secret_first_post.id),
        post_index.objects.fetch(secret_reply.id),
      )
      expect(post_index.objects.keys).to contain_exactly(
        secret_first_post.id,
        secret_reply.id,
        public_post.id,
      )
    end
  end
end

import didInsert from "@ember/render-modifiers/modifiers/did-insert";
import { apiInitializer } from "discourse/lib/api";
import { isDevelopment } from "discourse/lib/environment";
import loadScript from "discourse/lib/load-script";
import DiscourseURL from "discourse/lib/url";
import { i18n } from "discourse-i18n";

function initializeAutocomplete(options) {
  const algoliasearch = window.algoliasearch;
  const { autocomplete, getAlgoliaResults } =
    window["@algolia/autocomplete-js"];

  const autocompleteElement = document
    .getElementsByClassName("algolia-search")[0]
    .getElementsByClassName("aa-Autocomplete");
  if (autocompleteElement.length > 0) {
    return;
  }

  const searchClient = algoliasearch(
    options.algoliaApplicationId,
    options.algoliaSearchApiKey
  );
  const hitsPerPage = 4;

  const autocompleteSearch = autocomplete({
    container: ".algolia-search",
    panelContainer: ".algolia-autocomplete",
    debug: options.debug,
    detachedMediaQuery: "none",
    placeholder: i18n("discourse_algolia.search_box_placeholder"),
    getSources() {
      return [
        {
          sourceId: "posts",
          getItemInputValue: ({ item }) => item.query,
          getItems({ query }) {
            return getAlgoliaResults({
              searchClient,
              queries: [
                {
                  indexName: "discourse-posts",
                  query,
                  params: {
                    hitsPerPage,
                  },
                },
              ],
            });
          },
          templates: {
            item({ item, components, html }) {
              let tags = [];
              let baseTags = item.topic.tags;
              if (baseTags) {
                baseTags.forEach((baseTag, index) => {
                  // TODO(https://github.com/discourse/discourse/pull/36678): The string check can be
                  // removed using .discourse-compatibility once the PR is merged.
                  const tagPath =
                    typeof baseTag === "string"
                      ? `/tags/${baseTag}`
                      : `/tag/${baseTag.slug}/${baseTag.id}`;
                  tags.push(html`<a
                    class="hit-post-tag"
                    onClick="${(event) => {
                      DiscourseURL.routeTo(tagPath);
                      autocompleteSearch.setIsOpen(false);
                      event.preventDefault();
                      event.stopPropagation();
                    }}"
                  >
                    ${components.Highlight({
                      hit: item,
                      // TODO(https://github.com/discourse/discourse/pull/36678): The string check can be
                      // removed using .discourse-compatibility once the PR is merged.
                      attribute:
                        typeof baseTag === "string"
                          ? ["topic", "tags", index]
                          : ["topic", "tags", index, "name"],
                    })}
                  </a>`);
                });
              }
              return html` <div class="hit-post">
                <div class="hit-post-title-holder">
                  <span class="hit-post-topic-title">
                    ${components.Highlight({
                      hit: item,
                      attribute: ["topic", "title"],
                    })}
                  </span>
                  <span
                    class="hit-post-topic-views"
                    title="${i18n("discourse_algolia.topic_views")}"
                  >
                    ${item.topic.views}
                  </span>
                </div>
                <div class="hit-post-category-tags">
                  <span class="hit-post-category">
                    <span class="badge-wrapper bullet">
                      <span
                        class="badge-category-bg"
                        style="background-color: #${item.category?.color};"
                      />
                      <a
                        class="badge-category hit-post-category-name"
                        onClick="${(event) => {
                          DiscourseURL.routeTo(item.category.url);
                          autocompleteSearch.setIsOpen(false);
                          event.preventDefault();
                          event.stopPropagation();
                        }}"
                        >${item.category?.name}</a
                      >
                    </span>
                  </span>
                  <span class="hit-post-tags">${tags}</span>
                </div>
                <div class="hit-post-content-holder">
                  <a
                    class="hit-post-username"
                    onClick="${(event) => {
                      DiscourseURL.routeTo(item.user.url);
                      autocompleteSearch.setIsOpen(false);
                      event.preventDefault();
                      event.stopPropagation();
                    }}"
                    >@${item.user.username}</a
                  >:
                  <span class="hit-post-content">
                    ${components.Snippet({
                      hit: item,
                      attribute: "content",
                    })}
                  </span>
                </div>
              </div>`;
            },
            noResults({ html }) {
              return html`<div class="aa-empty">
                ${i18n("discourse_algolia.no_posts")}
              </div>`;
            },
          },
          onSelect({ item }) {
            DiscourseURL.routeTo(item.url);
          },
        },
        {
          sourceId: "users",
          getItemInputValue: ({ item }) => item.query,
          getItems({ query }) {
            return getAlgoliaResults({
              searchClient,
              queries: [
                {
                  indexName: "discourse-users",
                  query,
                  params: {
                    hitsPerPage,
                  },
                },
              ],
            });
          },
          templates: {
            item({ item, components, html }) {
              let likesElement = "";

              if (item.likes_received > 0) {
                likesElement = html`<span class="hit-user-like-heart">❤</span>
                  ${item.likes_received}`;
              }
              const usernameElement = components.Highlight({
                hit: item,
                attribute: item.name ? "name" : "username",
              });

              return html`<div class="hit-user-left">
                  <img
                    class="hit-user-avatar"
                    src="${options.imageBaseURL}${item.avatar_template.replace(
                      "{size}",
                      50
                    )}"
                  />
                </div>
                <div class="hit-user-right">
                  <div class="hit-user-username-holder">
                    <span class="hit-user-username">
                      @${components.Highlight({
                        hit: item,
                        attribute: "username",
                      })}
                    </span>
                    <span
                      class="hit-user-custom-ranking"
                      title="${i18n("discourse_algolia.user_likes")}"
                    >
                      ${likesElement}
                    </span>
                  </div>
                  <div class="hit-user-name">${usernameElement}</div>
                </div>`;
            },
          },
          onSelect({ item }) {
            DiscourseURL.routeTo(item.url);
          },
        },
        {
          sourceId: "tags",
          getItemInputValue: ({ item }) => item.query,
          getItems({ query }) {
            return getAlgoliaResults({
              searchClient,
              queries: [
                {
                  indexName: "discourse-tags",
                  query,
                  params: {
                    hitsPerPage,
                  },
                },
              ],
            });
          },
          templates: {
            item({ item, components, html }) {
              return html`<div class="hit-tag">
                #<span class="hit-tag-name">
                  ${components.Highlight({
                    hit: item,
                    attribute: "name",
                  })}</span
                >
                <span
                  class="hit-tag-topic_count"
                  title="${i18n("discourse_algolia.topic_tags")}"
                  >${item.topic_count}</span
                >
              </div> `;
            },
          },
          onSelect({ item }) {
            DiscourseURL.routeTo(item.url);
          },
        },
      ];
    },

    render({ elements, render, html }, root) {
      const { posts, users, tags } = elements;
      render(
        html`<div class="aa-dropdown-menu">
          <div class="left-container">
            <div class="aa-dataset-posts">${posts}</div>
          </div>
          <div class="right-container">
            <span class="aa-dataset-users">${users}</span>
            <span class="aa-dataset-tags">${tags}</span>
          </div>
          <div class="aa-footer">
            <div class="left-container">
              <a
                class="advanced-search"
                onClick="${(event) => {
                  DiscourseURL.routeTo("/search");
                  autocompleteSearch.setIsOpen(false);
                  event.preventDefault();
                  event.stopPropagation();
                }}"
                >${i18n("discourse_algolia.advanced_search")}</a
              >
            </div>
            <div class="right-container">
              <a
                target="_blank"
                class="algolia-logo"
                href="https://algolia.com/"
                title="${i18n("discourse_algolia.powered_by")}"
              ></a>
            </div>
          </div>
        </div>`,
        root
      );
    },
  });
  return autocompleteSearch;
}

export default apiInitializer((api) => {
  const siteSettings = api.container.lookup("service:site-settings");
  const site = api.container.lookup("service:site");
  const currentUser = api.getCurrentUser();
  const shouldDisplay = () =>
    siteSettings.algolia_enabled &&
    siteSettings.algolia_autocomplete_enabled &&
    siteSettings.algolia_application_id &&
    site.algolia_search_api_key &&
    (!siteSettings.login_required || currentUser);

  let search;

  function loadAlgoliaScripts() {
    return Promise.all([
      loadScript("/plugins/discourse-algolia/javascripts/autocomplete.js"),
      loadScript("/plugins/discourse-algolia/javascripts/algoliasearch.js"),
    ]);
  }

  async function renderAlgolia() {
    search?.destroy();

    try {
      await loadAlgoliaScripts();
    } catch {
      // Retry once
      await loadAlgoliaScripts();
    }

    document.body.classList.add("algolia-enabled");
    search = initializeAutocomplete({
      algoliaApplicationId: siteSettings.algolia_application_id,
      algoliaSearchApiKey: [REDACTED],
      imageBaseURL: "",
      debug: isDevelopment(),
    });
  }

  api.headerIcons.add(
    "algolia",
    <template>
      {{#if (shouldDisplay)}}
        <li class="algolia-holder" {{didInsert renderAlgolia}}>
          <div class="algolia-search"></div>
          <div class="algolia-autocomplete"></div>
        </li>
      {{/if}}
    </template>
  );
});

